64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Maximum number of owners a single city may hold. A create request whose city already contains
75	     * this many owners is rejected as a conflict.
76	     */
77	    static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /**
80	     * Maximum number of owners that may be registered on a single day. A create request whose
81	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
82	     */
83	    static final int MAX_OWNERS_PER_DAY = 100;
84	
85	    /**
86	     * Number of owners that may be registered on the current business day before a create/read
87	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
88	     * the warning is raised.
89	     */
90	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
91	
92	    private final ClinicService clinicService;
93	
94	    private final OwnerMapper ownerMapper;
95	
96	    private final PetMapper petMapper;
97	
98	    private final VisitMapper visitMapper;
99	
100	    private final OwnerAuditor ownerAuditor;
101	
102	    public OwnerRestControllerV1(ClinicService clinicService,
103	                                 OwnerMapper ownerMapper,
104	                                 PetMapper petMapper,
105	                                 VisitMapper visitMapper,
106	                                 OwnerAuditor ownerAuditor) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	        this.ownerAuditor = ownerAuditor;
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
117	        Collection<Owner> owners;
118	        if (lastName != null) {
119	            owners = this.clinicService.findOwnerByLastName(lastName);
120	        } else {
121	            owners = this.clinicService.findAllOwners();
122	        }
123	        if (owners.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
132	        Owner owner = this.clinicService.findOwnerById(ownerId);
133	        if (owner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(toOwnerDtoWithBulkSignupWarning(owner), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
142	        resolveAddress(ownerFieldsDto);
143	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
144	        if (!missingFields.isEmpty()) {
145	            throw new MissingOwnerFieldsException(missingFields);
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        if (!PostcodeValidator.isValidForCity(owner.getCity(), owner.getPostcode())) {
150	            throw new InvalidPostcodeException(owner.getPostcode(), owner.getCity());
151	        }
152	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
153	            throw new CityCapacityExceededException(owner.getCity());
154	        }
155	        if (RegistrationDatePolicy.isAfterServerDate(owner.getRegistrationDate())) {
156	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
157	        }
158	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
159	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
160	            throw new DailyOwnerLimitExceededException(registrationDate);
161	        }
162	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
163	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
164	        if (DisposableEmailValidator.isDisposable(owner.getEmail())) {
165	            throw new DisposableEmailException(owner.getEmail());
166	        }
167	        // The household is keyed on (last name, postcode): the id is deterministic, so owners with
168	        // the same last name and postcode share it automatically.
169	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
170	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
171	        owner.setDeclaredHouseholdMember(declaredHouseholdMember);
172	        // A second owner in an existing household is a duplicate, unless it declares shared
173	        // membership — in which case it is created as a known household member.
174	        if (!declaredHouseholdMember && this.clinicService.isHouseholdDuplicate(owner)) {
175	            throw new DuplicateIdentityException(owner.getIdentityKey());
176	        }
177	        this.clinicService.saveOwner(owner);
178	        this.ownerAuditor.ownerCreated(owner);
179	        OwnerDto ownerDto = toOwnerDtoWithBulkSignupWarning(owner);
180	        headers.setLocation(UriComponentsBuilder.newInstance()
181	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
182	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
183	    }
184	
185	    /**
186	     * Normalize the submitted address form and resolve the canonical stored {@code address}.
187	     * Whichever fields are supplied are normalized: the structured {@code addressLine1}/
188	     * {@code addressLine2} are kept (blank lines dropped to {@code null}), and {@code address}
189	     * is set to the composed structured address when {@code addressLine1} is present, otherwise
190	     * to the normalized flat {@code address}. Everything downstream reads the resolved
191	     * {@code address}, so it reflects the structured fields when present and the flat address
192	     * otherwise.
193	     */
194	    private void resolveAddress(OwnerFieldsDto ownerFieldsDto) {
195	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
196	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
197	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
198	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
199	        if (ownerFieldsDto.getAddressLine1() != null) {
200	            ownerFieldsDto.setAddress(
201	                AddressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
202	        } else {
203	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
204	        }
205	    }
206	
207	    /**
208	     * Map an owner to its DTO and stamp {@code bulkSignupWarning}, which reflects whether more than
209	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current
210	     * business day.
211	     */
212	    private OwnerDto toOwnerDtoWithBulkSignupWarning(Owner owner) {
213	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
214	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
215	        ownerDto.setBulkSignupWarning(
216	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
217	        return ownerDto;
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        currentOwner.setAddress(ownerFieldsDto.getAddress());
228	        currentOwner.setCity(ownerFieldsDto.getCity());
229	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
230	        currentOwner.setLastName(ownerFieldsDto.getLastName());
231	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
232	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
233	        this.clinicService.saveOwner(currentOwner);
234	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Transactional
239	    @Override
240	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner == null) {
243	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	        }
245	        this.clinicService.deleteOwner(owner);
246	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        HttpHeaders headers = new HttpHeaders();
257	        Pet pet = petMapper.toPet(petFieldsDto);
258	        owner.setId(ownerId);
259	        pet.setOwner(owner);
260	        pet.getType().setName(null);
261	        this.clinicService.savePet(pet);
262	        PetDto petDto = petMapper.toPetDto(pet);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
264	            .buildAndExpand(pet.getId()).toUri());
265	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
271	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
272	        if (currentOwner != null) {
273	            Pet currentPet = this.clinicService.findPetById(petId);
274	            if (currentPet != null) {
275	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
276	                currentPet.setName(petFieldsDto.getName());
277	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
278	                this.clinicService.savePet(currentPet);
279	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
280	            }
281	        }
282	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
288	        HttpHeaders headers = new HttpHeaders();
289	        Visit visit = visitMapper.toVisit(visitFieldsDto);
290	        Pet pet = new Pet();
291	        pet.setId(petId);
292	        visit.setPet(pet);
293	        this.clinicService.saveVisit(visit);
294	        VisitDto visitDto = visitMapper.toVisitDto(visit);
295	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
296	            .buildAndExpand(visit.getId()).toUri());
297	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
298	    }
299	
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
304	        Owner owner = this.clinicService.findOwnerById(ownerId);
305	        if (owner != null) {
306	            Pet pet = owner.getPet(petId);
307	            if (pet != null) {
308	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
309	            }
310	        }
311	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
312	    }
313	}
